-- The accept polarity of the completeness gate, one modelled column per relation the gate marks complete.
-- It is what says the gate refuses *unmodelled* names rather than
-- refusing names: an over-tight list would fail here and never fail the reject fixtures.
-- Values are counts and constants, not catalog identities, so the two engines agree
-- despite 18.6 also carrying every system catalog's rows in the same relations.
-- @setup
CREATE TYPE cat_mood AS ENUM ('sad', 'ok', 'happy');
CREATE TABLE cat_parent (
  id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  code TEXT NOT NULL,
  region VARCHAR(8) NOT NULL,
  CONSTRAINT cat_parent_code_region_uq UNIQUE (code, region)
);
CREATE TABLE cat_child (
  cid INT GENERATED BY DEFAULT AS IDENTITY,
  pid INT REFERENCES cat_parent(id) ON DELETE CASCADE,
  qty INT NOT NULL,
  label TEXT,
  price NUMERIC(10,2),
  m cat_mood,
  CONSTRAINT cat_child_qty_positive CHECK (qty > 0),
  -- Two columns, named out of position order: `conkey` is 18.6's `pull_var_clause`
  -- walk order (`{3,2}`), not the table's column order. Integer operands only —
  -- a text literal would drag in the deparser's recorded `''` vs `''::text`
  -- divergence, which is not this constraint's subject.
  CONSTRAINT cat_child_qty_pid CHECK (qty > 1 AND pid > 0)
);
CREATE INDEX cat_child_pid_idx ON cat_child (pid);
CREATE INDEX cat_child_lower_label_idx ON cat_child (lower(label));
CREATE INDEX cat_child_partial_idx ON cat_child (qty) WHERE qty > 10;
CREATE SEQUENCE cat_plain_seq START 5;

-- @test
SELECT
  (SELECT count(*) FROM pg_constraint c JOIN pg_class k ON k.oid = c.conrelid
     WHERE k.relname::text = 'cat_child' AND c.contype::text = 'c') AS con,
  (SELECT count(*) FROM pg_index i JOIN pg_class k ON k.oid = i.indrelid
     WHERE k.relname::text = 'cat_child' AND i.indisvalid) AS idx,
  (SELECT count(*) FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid
     WHERE t.typname::text = 'cat_mood') AS enums,
  (SELECT count(*) FROM pg_tables WHERE tablename::text = 'cat_child'
     AND hasindexes) AS tbls,
  (SELECT count(*) FROM pg_indexes WHERE indexname::text = 'cat_child_pid_idx') AS idxs,
  (SELECT count(*) FROM information_schema.sequences
     WHERE sequence_name::text = 'cat_plain_seq' AND increment::text = '1') AS seqs,
  (SELECT count(*) FROM information_schema.check_constraints
     WHERE constraint_name::text = 'cat_child_qty_positive') AS checks,
  (SELECT count(*) FROM information_schema.key_column_usage
     WHERE constraint_name::text = 'cat_parent_pkey') AS kcu,
  (SELECT count(*) FROM information_schema.referential_constraints
     WHERE constraint_name::text = 'cat_child_pid_fkey'
       AND delete_rule::text = 'CASCADE') AS rc,
  (SELECT count(*) FROM information_schema.constraint_column_usage
     WHERE constraint_name::text = 'cat_parent_pkey') AS ccu
